package ai.interviewiq.api.entity;
import jakarta.persistence.*; import java.time.Instant; import java.math.BigDecimal;
@Entity @Table(name="interview_feedback") public class InterviewFeedback extends BaseEntity { @OneToOne @JoinColumn(nullable=false,unique=true) private InterviewSession interviewSession; @Enumerated(EnumType.STRING) @Column(nullable=false) private FeedbackStatus status=FeedbackStatus.PENDING; @Column(precision=5,scale=2) private BigDecimal overallScore; @Column(columnDefinition="TEXT") private String overallAssessment; @Column(columnDefinition="TEXT") private String strengths; @Column(columnDefinition="TEXT") private String improvementAreas; @Column(columnDefinition="TEXT") private String recommendedActions; private Instant generatedAt; protected InterviewFeedback(){} public InterviewFeedback(InterviewSession s){interviewSession=s;} public void available(double score,String assessment,String strength,String improvement,String actions){status=FeedbackStatus.AVAILABLE;overallScore=BigDecimal.valueOf(score);overallAssessment=assessment;strengths=strength;improvementAreas=improvement;recommendedActions=actions;generatedAt=Instant.now();} public FeedbackStatus getStatus(){return status;} public Double getOverallScore(){return overallScore==null?null:overallScore.doubleValue();} public String getOverallAssessment(){return overallAssessment;} public String getStrengths(){return strengths;} public String getImprovementAreas(){return improvementAreas;} public String getRecommendedActions(){return recommendedActions;} public Instant getGeneratedAt(){return generatedAt;} }
